steps.sql:
SELECT c.nom, cmd.id
FROM   clients c, commandes cmd
WHERE  c.id = cmd.client_id;

SELECT c.nom, cmd.id, cmd.montant
FROM   clients c
INNER JOIN commandes cmd ON cmd.client_id = c.id;

SELECT c.nom, cmd.id, cmd.montant
FROM   clients c
LEFT JOIN commandes cmd ON cmd.client_id = c.id;

SELECT p.nom AS produit, cat.libelle AS categorie
FROM   produits p
FULL JOIN categories cat ON cat.id = p.categorie_id;

SELECT c.nom, cat.libelle
FROM   clients c
CROSS JOIN categories cat;

SELECT e.nom AS employe, chef.nom AS chef
FROM   employes e
JOIN   employes chef ON chef.id = e.chef_id;
